    part=rows[i*q:(i+1)*q] if i<3 else rows[3*q:]
    tot=collections.Counter()
    for _,t,_,_ in part: tot+=t
    sk=collections.Counter(s for _,_,ss,_ in part for s in ss)
    print(f"quartile {i+1}: reads/run {tot['Read']/len(part):.1f} greps {tot['Grep']/len(part):.1f} edits {(tot['Edit']+tot['MultiEdit']+tot['Write'])/len(part):.1f} bash {tot['Bash']/len(part):.1f} tasks {tot['Task']/len(part):.1f} skills used {sum(sk.values())} {dict(sk.most_common(4))}")
